/// Validates a document against an authoritative Draft 2020-12 schema.
pub fn validate_document(family: &str, document: &serde_json::Value) -> Result<(), SchemaError> {
    let source =
        schema_source(family).ok_or_else(|| SchemaError::UnknownFamily(family.to_owned()))?;
    let schema: serde_json::Value = serde_json::from_str(source)
        .map_err(|error| SchemaError::InvalidSchema(error.to_string()))?;
    let validator = jsonschema::draft202012::options()
        .should_validate_formats(true)
        .build(&schema)
        .map_err(|error| SchemaError::InvalidSchema(error.to_string()))?;
    validator
        .validate(document)
        .map_err(|error| SchemaError::InvalidDocument(error.to_string()))
}

fn decode_document<T>(family: &str, content: &[u8]) -> Result<T, SchemaError>
where
    T: serde::de::DeserializeOwned,
{
    let document: serde_json::Value =
        serde_json::from_slice(content).map_err(|error| SchemaError::Decode(error.to_string()))?;
    validate_document(family, &document)?;
    serde_json::from_value(document).map_err(|error| SchemaError::Decode(error.to_string()))
}

